-- public.artifact_refusal(p_world uuid, p_uid uuid, p_action text, c creature)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.artifact_refusal(p_world uuid, p_uid uuid, p_action text, c creature)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_def text := artifact_item(p_action); v_name text;
begin
  if c.mode = 'wild' then return 'Not yours.'; end if;
  if c.keeper is distinct from p_uid then return c.name || ': not yours.'; end if;
  if c.mode = 'stored' then return c.name || ' is in a wildermon crate: open it first.'; end if;
  v_name := lower((select name from item_def where id = v_def));
  -- A locked one is not offered up, as nothing else spends one (`consume`).
  if pack_count(p_world, p_uid, v_def) <= 0 then return 'Need ' || article(v_name) || ' ' || v_name || '.'; end if;
  if p_action = 'use_ancient_comb' and age_of(c.born, old_of(c), age_pace(c)) = 'young' then
    return c.name || ' is already young.';
  end if;
  if p_action = 'use_ancient_file' and c.rare is not null and rarity_next(c.rare) is null then
    return c.name || ' is already ' || c.rare || ', the top rarity.';
  end if;
  if p_action = 'use_bronze_mirror' and mirrored(c) then return c.name || ': already mirrored.'; end if;
  if p_action = 'use_bronze_mirror' and mirror_trait(c.traits) is null then return c.name || ': no traits to copy.'; end if;
  if p_action = 'use_ancient_brace' and brace_points(c) >= brace_most() then
    return c.name || ': ' || brace_most()::int || ' ancient brace uses, the max.';
  end if;
  if p_action = 'use_ancient_collar' and fitted(c, 'collar') then return c.name || ': ancient collar already fitted.'; end if;
  if p_action = 'use_ancient_bridle' and fitted(c, 'bridle') then return c.name || ': ancient bridle already fitted.'; end if;
  if p_action = 'use_ancient_pot' and not exists (select 1 from unnest(base_stats()) s where pot_points(c, s) < pot_most()) then
    return c.name || ': every base stat at ' || pot_most()::int || ' ancient pot points, the max.';
  end if;
  return null;
end $function$
